   332	int
   333	_gnutls_x509_write_spki_params(ASN1_TYPE dst, const char *dst_name,
   334	                               gnutls_x509_spki_st *params)
   335	{
   336	        const char *oid;
   337	
   338	        if (params->legacy && params->pk == GNUTLS_PK_RSA)
   339	                oid = PK_PKIX1_RSA_OID;
   340	        else if (params->pk == GNUTLS_PK_RSA_PSS)
   341	                oid = PK_PKIX1_RSA_PSS_OID;
   342	        else
   343	                oid = gnutls_pk_get_oid(params->pk);
   344	
   345	        if (oid == NULL) {
   346	                gnutls_assert();
   347	                _gnutls_debug_log
   348	                    ("Cannot find OID for public key algorithm %s\n",
   349	                     gnutls_pk_get_name(params->pk));
   350	                return GNUTLS_E_INVALID_REQUEST;
   351	        }
   352	
   353	        return write_oid_and_params(dst, dst_name, oid, params);
   354	}
