   357	_gnutls_x509_write_sign_params(ASN1_TYPE dst, const char *dst_name,
   358	                               const gnutls_sign_entry_st *se, gnutls_x509_spki_st *params)
   359	{
   360	        const char *oid;
   361	
   362	        if (params->legacy && params->pk == GNUTLS_PK_RSA)
   363	                oid = PK_PKIX1_RSA_OID;
   364	        else if (params->pk == GNUTLS_PK_RSA_PSS)
   365	                oid = PK_PKIX1_RSA_PSS_OID;
   366	        else
   367	                oid = se->oid;
   368	
   369	        if (oid == NULL) {
   370	                gnutls_assert();
   371	                _gnutls_debug_log
   372	                    ("Cannot find OID for sign algorithm %s\n",
   373	                     se->name);
   374	                return GNUTLS_E_INVALID_REQUEST;
   375	        }
   376	
   377	        return write_oid_and_params(dst, dst_name, oid, params);
