   430	/* Writes the specified integer into the specified node.
   431	 */
   432	int
   433	_gnutls_x509_write_uint32(ASN1_TYPE node, const char *value, uint32_t num)
   434	{
   435	        uint8_t tmpstr[5];
   436	        int result;
   437	
   438	        tmpstr[0] = 0;
   439	        _gnutls_write_uint32(num, tmpstr+1);
   440	
   441	        if (tmpstr[1] > SCHAR_MAX) {
   442	                result = asn1_write_value(node, value, tmpstr, 5);
   443	        } else {
   444	                result = asn1_write_value(node, value, tmpstr+1, 4);
   445	        }
   446	
   447	        if (result != ASN1_SUCCESS) {
   448	                gnutls_assert();
   449	                return _gnutls_asn2err(result);
   450	        }
   451	
   452	        return 0;
   453	}
